        if (stake == 0) return (0, 0, 0);
        uint256 seedPerSide   = protocolSeedTotal / 2;
        uint256 winningSide   = (greaterThan ? greaterPool : lessEqualPool) - seedPerSide + stake;
        uint256 distributable = totalPool - protocolSeedTotal + stake;
